command:
cat > pipeline.py <<'EOF'
import csv
import json
import math
import os
from datetime import datetime, timezone

SRC = "data/orders.csv"
DST = "out/summary.json"


def parse_ts(value):
    """Best-effort parse of an updated_at timestamp into a naive UTC datetime."""
    if value is None:
        return None
    s = str(value).strip()
    if not s:
        return None
    dt = None
    try:
        dt = datetime.fromisoformat(s.replace("Z", "+00:00"))
    except ValueError:
        for fmt in ("%Y-%m-%dT%H:%M:%S", "%Y-%m-%d %H:%M:%S", "%Y-%m-%d",
                    "%m/%d/%Y %H:%M:%S", "%m/%d/%Y"):
            try:
                dt = datetime.strptime(s, fmt)
                break
            except ValueError:
                continue
    if dt is None:
        return None
    if dt.tzinfo is not None:
        dt = dt.astimezone(timezone.utc).replace(tzinfo=None)
    return dt


def parse_amount(value):
    """Return float amount, or None when the value is not a real number."""
    if value is None:
        return None
    s = str(value).strip()
    if not s:
        return None
    s = s.replace("$", "").replace(",", "").strip()
    try:
        amt = float(s)
    except (TypeError, ValueError):
        return None
    if not math.isfinite(amt):
        return None
    return amt


def main():
    os.makedirs("out", exist_ok=True)

    # 1. Deduplicate by order_id, keeping the row with the latest updated_at.
    latest = {}
    latest_ts = {}
    with open(SRC, newline="", encoding="utf-8-sig") as f:
        for row in csv.DictReader(f):
            oid = (row.get("order_id") or "").strip()
            ts = parse_ts(row.get("updated_at"))
            if oid not in latest:
                latest[oid] = row
                latest_ts[oid] = ts
            else:
                cur = latest_ts[oid]
                if cur is None or ts is None or ts >= cur:
                    if cur is None and ts is None:
                        continue
                    if ts is not None or cur is None:
                        latest[oid] = row
                        latest_ts[oid] = ts

    total = 0.0
    customers = set()
    for row in latest.values():
        # 2. Skip rows whose amount_usd is not a number.
        amt = parse_amount(row.get("amount_usd"))
        if amt is None:
            continue
        # 3. Only completed rows count.
        if (row.get("status") or "").strip().lower() != "completed":
            continue
        total += amt
        cid = (row.get("customer_id") or "").strip()
        if cid:
            customers.add(cid)

    summary = {
        "total_completed_usd": round(total, 2),
        "unique_completed_customers": len(customers),
    }
    with open(DST, "w", encoding="utf-8") as f:
        json.dump(summary, f, indent=2)
        f.write("\n")


if __name__ == "__main__":
    main()
EOF
python3 pipeline.py && cat out/summary.json
